            return block.TopicIds;
        }

        var weak = hinted.ToHashSet();
        // The block's own position is the tie-break, so two runs plan the same month.
        var position = block.TopicIds
            .Select((topicId, index) => (topicId, index))
            .ToDictionary(x => x.topicId, x => x.index);

        return block.TopicIds
            .OrderByDescending(weak.Contains)
            .ThenBy(t => position[t])
            .ToList();
    }

