    /// </summary>
    public static bool IsWeekOnTrack(
        int plannedSteps,
        int completedSteps,
        decimal? averageAccuracy,
        int targetAccuracyPct)
    {
        if (plannedSteps <= 0)
        {
            return false;
        }

        if (completedSteps * 100 < plannedSteps * 80)
        {
            return false;
        }

        return averageAccuracy is null || averageAccuracy.Value >= targetAccuracyPct;
    }

